/** GENERATED by the build - replaces the Eztrade lockup with the tenant brand. */
import { BRAND } from "@/lib/brand.generated";

type Props = { className?: string; width?: number | string; height?: number | string; wordmark?: boolean };

export function EztradeLogo({ className, width, height, wordmark = true }: Props) {
  const h = typeof height === "number" ? height : 20;
  if (BRAND.logoUrl) {
    const side = Math.max(h, 28);
    return <img src={BRAND.logoUrl} alt={BRAND.name} className={className} style={{ height: side, width: "auto", maxWidth: 220, objectFit: "contain", display: "block" }} />;
  }
  if (!wordmark) {
    return (
      <span className={className} aria-label={BRAND.name} style={{ display: "inline-grid", placeItems: "center", width: width ?? 32, height: h, fontWeight: 800, fontSize: Math.round(h * 0.9), lineHeight: 1, color: "var(--logo-wordmark, currentColor)" }}>
        {BRAND.name.charAt(0).toUpperCase()}
      </span>
    );
  }
  return (
    <span className={className} aria-label={BRAND.name} style={{ display: "inline-flex", alignItems: "center", width: width ?? "auto", height: h, fontWeight: 800, letterSpacing: "0.04em", fontSize: Math.round(h * 0.95), lineHeight: 1, whiteSpace: "nowrap", color: "var(--logo-wordmark, currentColor)" }}>
      {BRAND.name.toUpperCase()}
    </span>
  );
}
